import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineVat } from './invoices.js';
import { roundCents } from './money.js';

export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
    .filter(inv => inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) continue;

    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const subtotal = lineTotal(line);
      const discount = line.discountPercent ? subtotal * line.discountPercent / 100 : 0;
      const base = Math.max(0, subtotal - discount);
      const vat = lineVat(line);

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { rate, base: 0, vat: 0 });
      }
      const entry = vatMap.get(rate);
      entry.base += base;
      entry.vat += vat;
    }
  }

  return Array.from(vatMap.values())
    .map(entry => ({
      rate: entry.rate,
      base: roundCents(entry.base),
      vat: roundCents(entry.vat),
    }))
    .sort((a, b) => b.rate - a.rate);
}

export function lateFee(invoice, asOf) {
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) return 0;
  const amountDue = balanceDue(invoice);
  return roundCents(amountDue * 0.0004 * daysOverdue);
}

