  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 20);
  assert.equal(result[1].rate, 10);
});

test('vatSummary sums bases for same VAT rate', () => {
  const invoices = [
    { status: 'issued', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    { status: 'issued', lines: [{ qty: 1, unitPrice: 500, discountPercent: 0, vatRate: 20 }] },
  ];
  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, 1500);
});

test('vatSummary sums VAT for same rate', () => {
  const invoices = [
    { status: 'issued', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
    { status: 'issued', lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }] },
