  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].vat, 400);
});

test('vatSummary sorts by rate descending', () => {
  const invoices = [
    { status: 'issued', lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 10 }] },
